function useAgent(slug) {
  const [agent, setAgent] = useState(null)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState(null)
  useEffect(() => {
    if (!slug) return
    const query = 'filter[slug][_eq]=' + encodeURIComponent(slug) + '&fields=*&limit=1'
    const url = `/api/directus?path=/items/agents&query=${encodeURIComponent(query)}`
    setLoading(true)
    fetch(url)
      .then(r => r.json())
      .then(json => { setAgent(json.data?.[0] || null); setLoading(false) })
      .catch(err => { setError(err); setLoading(false) })
  }, [slug])
  return { agent, loading, error }
}

function useAgentProperties(agentSlug) {
  const [properties, setProperties] = useState([])
  useEffect(() => {
    if (!agentSlug) return
    const query = 'filter[agent_slug][_eq]=' + encodeURIComponent(agentSlug) + '&fields=id,title,slug,listing_type,property_type,city_slug,price,currency,bedrooms,bathrooms,area_m2,cover_image,short_description&limit=6'
    fetch(`/api/directus?path=/items/properties&query=${encodeURIComponent(query)}`)
      .then(r => r.json())
      .then(json => setProperties(json.data || []))
      .catch(() => {})
  }, [agentSlug])
  return { properties }
}

